SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#efe8ff");
  let agua = 0;
  let sol = 3;
  let tempo = 0;
  let crescimento = 0;
  let florida = false;
  let recado = "Regue e dê sol. A cada segundo a flor usa um de cada para crescer.";
  const flor = SZGame2D.createSprite({ x: 272, y: 236, w: 96, h: 120, image: "muda" });
  const regar = SZGame2D.createSprite({ x: 120, y: 424, w: 172, h: 44, image: "botao" });
  const darSol = SZGame2D.createSprite({ x: 348, y: 424, w: 172, h: 44, image: "botao" });
  const botoesRegar = SZGame2D.createGroup();
  SZGame2D.addToGroup(botoesRegar, regar);
  const botoesSol = SZGame2D.createGroup();
  SZGame2D.addToGroup(botoesSol, darSol);
  // Quando acontecer
  SZGame2D.onGroupClick(botoesRegar, function (botao) {
    agua = agua + 3;
  }, "nuvens_chuva_events_0");
  SZGame2D.onGroupClick(botoesSol, function (botao) {
    sol = sol + 3;
  }, "nuvens_chuva_events_1");
  SZGame2D.onKey("Enter", () => {
    agua = 0;
    sol = 3;
    tempo = 0;
    crescimento = 0;
    florida = false;
    recado = "Regue e dê sol. A cada segundo a flor usa um de cada para crescer.";
  }, "nuvens_chuva_events_2");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function __szPeriodicLoop() {
    if (SZGame2D.everySeconds("simulacao", 1)) {
      tempo = tempo + 1;
      agua = agua + 1;
      if (agua > 0 && sol > 0) {
        crescimento = crescimento + 10;
        agua = agua - 1;
        sol = sol - 1;
      }
      if (crescimento >= 100 && florida === false) {
        florida = true;
        recado = "O jardim floresceu.";
      }
    }
  });
  SZGame2D.gameLoop(function update() {
    if (crescimento >= 100) {
      SZGame2D.setImage(flor, "flor");
    } else {
      if (crescimento >= 40) {
        SZGame2D.setImage(flor, "botaoFlor");
      } else {
        SZGame2D.setImage(flor, "muda");
      }
    }
    SZGame2D.clear();
    SZGame2D.drawBackdrop(ctx, "jardim");
    SZGame2D.drawLabel(ctx, "Jardim que floresce", 18, 32, "#3b2f6b", 25, "left");
    SZGame2D.drawLabel(ctx, recado, 18, 61, "#3b2f6b", 15, "left");
    SZGame2D.drawScore(ctx, "Água: ", agua, 18, 100, "#3b2f6b", 18);
    SZGame2D.drawScore(ctx, "Sol: ", sol, 18, 126, "#3b2f6b", 18);
    SZGame2D.drawScore(ctx, "Tempo: ", tempo, 470, 100, "#3b2f6b", 18);
    SZGame2D.drawScore(ctx, "Crescimento: ", crescimento, 470, 126, "#3b2f6b", 18);
    SZGame2D.drawSprite(ctx, flor);
    SZGame2D.drawSprite(ctx, regar);
    SZGame2D.drawSprite(ctx, darSol);
    SZGame2D.drawLabel(ctx, "Regar", 178, 451, "#ffffff", 18, "left");
    SZGame2D.drawLabel(ctx, "Sol", 420, 451, "#ffffff", 18, "left");
  }, "nuvens_chuva_loops_1");
}, "__sz-project");
